describe('File Upload - Invalid File Type Error Handling', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should display error message when uploading an unsupported file type', () => {
    // Attempt to upload a non-allowed file type (e.g., .exe)
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/unsupported.exe', {
      force: true
    });

    // Verify error message appears
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Unsupported file type');

    // Verify upload button is disabled or action is blocked
    cy.get('[data-testid="upload-button"]').should('be.disabled');

    // Verify file input value is still present
    cy.get('[data-testid="file-input"]').should('have.value', 'cypress/fixtures/unsupported.exe');
  });

  it('should allow upload when a supported file type is selected and clear error message', () => {
    // Upload a supported file type (e.g., .pdf)
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/document.pdf', {
      force: true
    });

    // Verify error message is not visible
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify upload button is enabled
    cy.get('[data-testid="upload-button"]').should('not.be.disabled');

    // Click upload button to proceed
    cy.get('[data-testid="upload-button"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .should('contain', 'File uploaded successfully');

    // Verify error message is cleared
    cy.get('[data-testid="error-message"]').should('not.exist');
  });
});
